def babylonian_sqrt(n, tolerance=1e-10, max_iterations=1000):
    if n < 0:
        raise ValueError("Cannot compute square root of a negative number")
    if n == 0:
        return 0
    guess = n
    while max_iterations > 0:
        better_guess = (guess + n / guess) / 2
        if abs(guess - better_guess) < tolerance:
            return better_guess
        guess = better_guess
        max_iterations -= 1
    return guess
```

