def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def nth_newman_shanks_williams_prime(n):
    def is_nsw_prime(p):
        a, b = 1, 1
        while True:
            a, b = b, 2 * b + a
            if is_prime(a):
                return a == p
            a, b = b, 2 * b - a
            if is_prime(a):
                return a == p
            a, b = b, 2 * b + a
            if is_prime(a):
                return a == p
            a, b = b, 2 * b - a
            if is_prime(a):
                return a == p

    count = 0
    p = 2
    while True:
        if is_nsw_prime(p):
            count += 1
            if count == n:
                return p
        p += 1

